Q: UICollectionView Top spacing A: <p>The an above did not help me. But I noticed that <strong><code>NSCollectionLayoutSection</code></strong> with <strong><code>.grouped</code></strong> <strong><code>UICollectionLayoutListConfiguration</code></strong> sets the <code>contentInset</code> for <strong>top</strong> and <strong>bottom.</strong> I don't have any idea why Apple did that, but the solution for me is just to set <strong><code>contentInsets = .zero</code>.</strong> Full code snipped:</p>
<pre><code>extension NSCollectionLayoutSection {
    static func tableList(layoutEnvironment: NSCollectionLayoutEnvironment) -&gt; NSCollectionLayoutSection {
        var configuration: UICollectionLayoutListConfiguration = .init(appearance: .grouped)
        configuration.showsSeparators = false

        if #available(iOS 15.0, *) {
            configuration.headerTopPadding = 0
        }

        let section: NSCollectionLayoutSection = .list(using: configuration,
                            layoutEnvironment: layoutEnvironment)

        section.contentInsets = .zero

        return section
    }
}
</code></pre>
